package org.com.sharekhan.analysis;
import org.junit.jupiter.api.Test;
import org.com.sharekhan.service.SharekhanHistoricalService.HistoricalCandle;
import java.time.*;import java.util.*;import java.nio.file.*;
import com.fasterxml.jackson.databind.ObjectMapper;import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class CompanyAnalysisTest {
 final LocalDate day=LocalDate.of(2026,10,30);
 final SavedDailyAnalysis daily=mock(SavedDailyAnalysis.class);
 final WeeklyTechnicalService weekly=mock(WeeklyTechnicalService.class);
 final CompanyAnalysisService service=new CompanyAnalysisService(daily,weekly);
 final StockDailyHistoryStore.Member member=new StockDailyHistoryStore.Member("DEMO","INEDEMO",day);
 StockAnalysisService.Report prices(){return StockAnalysisService.calculate(new StockAnalysisService.Instrument(null,"DEMO","NC"),"SWING",new WeeklyTechnicalTest().bars(day,420),Instant.parse("2026-11-01T20:00:00Z"),SavedDailyAnalysis.PROVIDER,List.of(),day);}
 WeeklyTechnicalService.Report chart(){return new WeeklyTechnicalTest().eval(new WeeklyTechnicalTest().bars(day,420),day);}
 CompanyAnalysisService.Financials evidence(){return new CompanyAnalysisService.Financials("DEMO","https://example.com/annual-report.pdf",LocalDate.of(2026,5,1),LocalDate.of(2026,3,31),"CONSOLIDATED_ANNUAL",10.,40.,120.,100.,12.,18.,4.,20.,80.);}
 CompanyAnalysisService.Report result(CompanyAnalysisService.Financials f){return service.assemble(member,prices(),chart(),f);}
 Double metric(CompanyAnalysisService.Report r,String n){return r.metrics().stream().filter(m->m.name().equals(n)).findFirst().orElseThrow().value();}
 @Test void missingEvidenceCannotBecomeRecommendation(){var r=result(null);assertThat(r.financialStatus()).isEqualTo("MISSING");assertThat(r.status()).isEqualTo("REVIEW_REQUIRED");assertThat(r.metrics()).isEmpty();assertThat(r.financials()).isNull();assertThat(r.missing()).anyMatch(s->s.contains("financial statements"));assertThat(r.rules()).anyMatch(s->s.contains("BSE"));}
 @Test void ratiosUseAnnualInrUnitsAndNoTargetOrScore(){var r=result(evidence());assertThat(r.financialStatus()).isEqualTo("USER_SUPPLIED_UNVERIFIED");assertThat(metric(r,"Annual P/E")).isCloseTo(prices().candles().getLast().close()/10,within(1e-8));assertThat(metric(r,"Price / book")).isCloseTo(prices().candles().getLast().close()/40,within(1e-8));assertThat(metric(r,"Annual revenue growth")).isCloseTo(20,within(1e-8));assertThat(metric(r,"Free cash flow")).isEqualTo(14);assertThat(metric(r,"Net margin")).isEqualTo(10);assertThat(metric(r,"Debt / equity")).isEqualTo(.25);assertThat(metric(r,"Cash conversion")).isEqualTo(1.5);assertThat(r.status()).isEqualTo("REVIEW_REQUIRED");assertThat(r.missing()).anyMatch(s->s.contains("Independent verification"));}
 @Test void missingInputsStayNullAndLossesDoNotCreateMultiples(){var f=evidence();var r=result(new CompanyAnalysisService.Financials(f.symbol(),f.sourceUrl(),f.publishedDate(),f.periodEnd(),f.basis(),-10.,-40.,120.,0.,-12.,null,null,20.,0.));for(String n:List.of("Annual P/E","Price / book","Debt / equity","Cash conversion","Free cash flow","Annual revenue growth"))assertThat(metric(r,n)).as(n).isNull();assertThat(r.risks()).anyMatch(s->s.contains("nonpositive"));}
 @Test void staleFinancialsWithholdAllMetrics(){var f=evidence();var r=result(new CompanyAnalysisService.Financials(f.symbol(),f.sourceUrl(),LocalDate.of(2025,5,1),LocalDate.of(2024,3,31),f.basis(),10.,40.,120.,100.,12.,18.,4.,20.,80.));assertThat(r.financialStatus()).isEqualTo("STALE_USER_SUPPLIED");assertThat(r.metrics()).isEmpty();assertThat(r.risks()).anyMatch(s->s.contains("540 days"));}
 @Test void stalePricesWithholdPriceBasedMultiplesButNotAnnualMargin(){var d=prices();var stale=new StockAnalysisService.Report(d.instrument(),d.mode(),d.interval(),d.provider(),d.timezone(),d.fetchedAt(),d.asOf(),"STALE",d.trend(),d.received(),d.rejected(),d.duplicates(),d.gaps(),d.candles(),d.indicators(),d.checks(),d.warnings());var r=service.assemble(member,stale,chart(),evidence());assertThat(metric(r,"Annual P/E")).isNull();assertThat(metric(r,"Price / book")).isNull();assertThat(metric(r,"Net margin")).isEqualTo(10);}
 @Test void validateRejectsWrongSymbolFuturePublicationAndWrongBasis(){var f=evidence();assertThatThrownBy(()->CompanyAnalysisService.validate("OTHER",f,day)).hasMessageContaining("symbol");assertThatThrownBy(()->CompanyAnalysisService.validate("DEMO",f,day.minusYears(1))).hasMessageContaining("publication");assertThatThrownBy(()->CompanyAnalysisService.validate("DEMO",new CompanyAnalysisService.Financials("DEMO",f.sourceUrl(),f.publishedDate(),f.periodEnd(),"QUARTERLY",10.,null,null,null,null,null,null,null,null),day)).hasMessageContaining("annual");}
 @Test void urlValidationNeverAllowsCredentialsOrNonHttps(){for(String u:List.of("file:///etc/passwd","http://example.com/report","https://user:password@example.com/","https://example.com:443/report","https://example.com/report#fragment","javascript:alert(1)")){var f=evidence();assertThatThrownBy(()->CompanyAnalysisService.validate("DEMO",new CompanyAnalysisService.Financials("DEMO",u,f.publishedDate(),f.periodEnd(),f.basis(),10.,null,null,null,null,null,null,null,null),day)).hasMessageContaining("HTTPS");}}
 @Test void numericValidationRejectsNanInfinityOversizedAndNegativeOutflows(){var f=evidence();for(double v:new double[]{Double.NaN,Double.POSITIVE_INFINITY,1e13})assertThatThrownBy(()->result(new CompanyAnalysisService.Financials("DEMO",f.sourceUrl(),f.publishedDate(),f.periodEnd(),f.basis(),v,null,null,null,null,null,null,null,null))).hasMessageContaining("finite");assertThatThrownBy(()->result(new CompanyAnalysisService.Financials("DEMO",f.sourceUrl(),f.publishedDate(),f.periodEnd(),f.basis(),10.,null,null,null,null,null,-1.,null,null))).hasMessageContaining("nonnegative");}
 @Test void symbolWhitelistReadsOnlyExistingSavedDatasets(){when(daily.members()).thenReturn(List.of(member));when(daily.analyze(eq("NC"),eq("DEMO"),any())).thenReturn(prices());when(weekly.report("DEMO")).thenReturn(chart());assertThat(service.report(" demo ",null).symbol()).isEqualTo("DEMO");verify(daily).analyze(eq("NC"),eq("DEMO"),any());assertThatThrownBy(()->service.report("../etc",null)).hasMessageContaining("Invalid");assertThatThrownBy(()->service.report("MISSING",null)).hasMessageContaining("No saved");}
 @Test void writeExplicitSyntheticBrowserFixture()throws Exception{var mapper=new ObjectMapper().registerModule(new JavaTimeModule()).disable(com.fasterxml.jackson.databind.SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);Files.writeString(Path.of("target/company-fixture.json"),mapper.writeValueAsString(Map.of("report",result(null),"withFinancials",result(evidence()),"symbols",List.of("DEMO","OTHER"))));}
}
